import sys
from collections import defaultdict

def construct_new_graph(n, m, edges):
    # Build a graph with degrees of nodes
    degree = [0] * n
    for u, v in edges:
        degree[u - 1] += 1
        degree[v - 1] += 1

    # Check if it's possible to form a graph based on input
    if sum(degree) % 2 != 0 or max(degree) - min(degree) > 2:
        return -1

    def dfs(start, edge_set, neighbors):
        for neighbor in neighbors[start]:
            edge = (start, neighbor)
            if edge in edge_set:
                continue
            edge_set.add(edge)
            dfs(neighbor, edge_set, neighbors)

    # Perform DFS from nodes with degree 1
    edge_set = set()
    for i in range(n):
        if degree[i] == 1:
            dfs(i, edge_set, defaultdict(lambda: [i]))

    # Build the graph
    graph = {node: [] for node in range(n)}
    for edge in edge_set:
        u, v = edge
        graph[u].append(v)
        graph[v].append(u)

    return [(u + 1, v + 1) for u, v in sorted(edges)]

def main():
    n, m = map(int, input().split())
    edges = [list(map(int, input().split())) for _ in range(m)]

    new_graph = construct_new_graph(n, m, edges)
