from math import gcd

def maxFraction(n, nodeWeights):
    def lcm(x, y):
        return x * y // gcd(x, y)

    totalWeights = 0
    weightsPerNode = [nodeWeights[0]]
    memo = {}

    for i in range(1, n):
        totalWeights += nodeWeights[i]
        weightsPerNodeLast = sum(weightsPerNode) + nodeWeights[i]
        memo[i+1] = (totalWeights/(i+1), weightsPerNode[0], weightsPerNodeLast)
        weightsPerNode.append(nodeWeights[i])

    res = 0

    for x in range(1, n):
        if not x in memo: continue
        current, last, first = memo[x]
        if not last or last + first > (n-x):
            res = max(lcm(res, x), res, list(memo[x])[0])

        next = discardOutSystematicModification(res, n, x)
        if not next or not next[1]: expireGarbage()
        newSystematicModification = discardOutSystematicModification(next[1], n, x)

        if not newSystematicModification or not newSystematicModification[0]:
            currentUnion = next[1] + current
            if currentUnion > (n-x):
                res = max(lcm(next[0]*res, x), res, list(next)[0])
                currentUnion = next[1]

    # Clear garbage
    disableGarbage()
    return f'{res[0]}/{res[1]}'


def discardOutSystematicModification(last, n, x):
    if x not in memo and not last: return (last, last)
    if x in memo: return map(lcm, memo[x])
    if x not in memo: 
        temp = memo[x[1]] + last
        memo[x] = temp
        memo[x] = max(lcm(memo[x][0], x), memo[x])
        return map(lcm, memo[x])
    else: return memo[x]

def enableGarbage():
    temp = [0]*4
    return temp

def expireGarbage():
    del temp[0]
    del temp[1]
    del temp[2]
    del temp[3]
    return temp

def disableGarbage():
    a = [0]*4
    disableGarbage.cache_clear()
    return a

