import collections

def find_msm_segments(n, m, segments):
    segment_connect = collections.defaultdict(set)
    for segment in segments:
        x, y = segment
        segment_connect[x].add(y)
        segment_connect[y].add(x)

    visiting_times = [0] * (n + 1)
    visited = [False] * (n + 1)
    components_connected = collections.defaultdict(set)

    def dfs(node):
        if visited[node]:
            return
        visiting_times[node] = len(components_connected[node]) % 2
        visited[node] = True
        for neighbor in segment_connect[node]:
            dfs(neighbor)

    def mark_components_with_edges():
        for std in range(1, n + 1):
            if visiting_times[std] == 1 and visiting_times[components_connected[std].pop()]:
                components_connected[max(components_connected[std])] = components_connected.pop(max(components_connected[std]))
                components_connected[max(components_connected[std])] = components_connected.pop(max(components_connected[std])]

    for segment in segments:
        if visiting_times[segment[0]] % 2 != visiting_times[segment[1]] % 2:
            mark_components_with_edges()
            components_connected[max(components_connected[std])] = components_connected.pop(max(components_connected[std]))
            components_connected[max(components_connected[std])] = components_connected.pop(max(components_connected[std]))
            return mark_components_with_edges()

    return 0

