import sys

def remove_adjacent_latin_parity(s, A):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    remaining = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if A[i][j] == 1:
                dp[i][j] = 1
                if i == 0 or j == 0:
                    dp[i][j] = 0
                else:
                    dp[i][j] += dp[i-1][j-1]
                remaining[i][j] = 1
    for i in range(n):
        for j in reversed(range(n)):
            remaining[i][j] += remaining[i][j + 1]
    for i in reversed(range(n)):
        for j in range(n):
            remaining[i][j] += remaining[i - 1][j]
    result = 0
    for i in range(1, n):
        for j in range(1, n):
            if dp[i][j] > remaining[i-1][j] and dp[i][j] > remaining[i][j-1] and len(s[:i] + s[i+1:]) < result:
                result = len(s[:i] + s[i+1:])
    return result

