from collections import deque, defaultdict

def get_shortest_non_adjacent_string(n, max_prefix_length, strings, adjacency_matrix):
    # Initialize the dynamic programming table
    dp = defaultdict(lambda: 0)
    dp[(0, 0)] = 0  # State with (curr_index, curr_prefix_length)
    queue = deque([(0, 0)])

    while queue:
        curr_index, curr_prefix_length = queue.popleft()

        # Check if the current string is a valid prefix to be removed
        if len(strings[curr_index]) == curr_prefix_length:
            dp[(curr_index, curr_prefix_length)] = len(strings[curr_index])

        # Try to remove one character starting from the current index
        for skip in [1, 2, 3]:
            if dp[(curr_index, curr_prefix_length)] == 0 or dp[(curr_index, curr_prefix_length) + skip] == 0:
                # Skip the character
                if skip == 1:
                    dp[(curr_index + (skip // max_prefix_length), curr_prefix_length + skip)] = 0
                if skip == 2:
                    dp[(curr_index + 1, curr_prefix_length + skip)] = len(strings[curr_index + 1])
                    dp[(curr_index + 1, curr_prefix_length + skip - 1)] = len(strings[curr_index + 1]) + 1
                if skip == 3:
                    dp[(curr_index + skip // max_prefix_length, curr_prefix_length + skip)] = len(strings[curr_index]) + 1

        for i in range(n - 1, -1, -1):
            if dp[(curr_index, curr_prefix_length)] == 0 or dp[(curr_index, curr_prefix_length) + 1] == 0:
                j = (i + curr_prefix_length) % n
                if adjacency_matrix[j][i] == 1:
                    dp[(curr_index + 1, curr_prefix_length + 1)] = dp[(curr_index, curr_prefix_length)]
                else:
                    dp[(curr_index + 1, curr_prefix_length + 1)] = dp[(0, 0)]

    return dp[(n, 0)]

if __name__ == "__main__":
    n, p = map(int, input().strip().split())
    strings = input().strip()
    adjacency_matrix = [list(map(int, input().split())) for _ in range(p)]

    shortest_length = get_shortest_non_adjacent_string(n, p, strings, adjacency_matrix)
    print(shortest_length)
