from collections import defaultdict

def find_missing_segments(n, m, points, segments):
    # Step 1: Find all pairs of points who are actually connected
    connected_pairs = defaultdict(list)
    for u, v in segments:
        connected_pairs[u].append(v)
        connected_pairs[v].append(u)

    # Step 2: Create a graph to check which edges are missing
    graph = defaultdict(set)
    for u, v in segments:
        graph[u].add(v)
        graph[v].add(u)

    # Step 3: Traverse each point in order to check its match
    missing_segments = []
    visited = [False] * n
    used = defaultdict(bool)

    for u in range(n):
        if used[u]:
            continue
        if dp_search(graph, u, n, visited):
            used[u] = True
        missing_segments.append(points[u])

    return (len(missing_segments), missing_segments)

def dp_search(graph, curr, n, visited):
    if visited[curr]:
        return True
    visited[curr] = True
    if graph[curr] is None:
        return False
    for neighbour in graph[curr]:
        if not visited[neighbour] and dp_search(graph, neighbour, n, visited):
            return True
    return False

