from heapq import heappush, heappop

def build_escape(plan):
    cities = [0]
    for city in plan:
        if city not in cities:
            cities += 2 * [city]
    if len(cities) < 4:
        return -1
    roots = cities
    h = []
    for c in plan:
        if c in cities:
            root = find_root(c, roots)
            residues = find_residues(root, roots)
            for r in residues:
                heappush(h, r)
    d = -heappop(h)
    while h:
        d = max(d, -heappop(h))
    return len(cities) - len(plan) - d

def find_root(v, roots):
    if roots[v] != v:
        roots[v] = find_root(roots[v], roots)
    return roots[v]

def find_residues(v, roots):
    residues = []
    while roots[v] != v:
        roots[v] = v
        v = roots[v]
    roots[v] = -1
    while v in roots:
        roots[v] = roots[v]
        v = roots[v]
        residues.append(v)
    return residues

