import sys

def rotate(polygon, rotate_by):
    """Rotate a polygon around a given point."""
    new_polygon = []
    for point in polygon:
        new_x = (point[0] - rotate_by[0]) * math.cos(math.radians(rotate_by[1])) - (point[1] - rotate_by[1]) * math.sin(math.radians(rotate_by[1])) + rotate_by[0]
        new_y = (point[0] - rotate_by[0]) * math.sin(math.radians(rotate_by[1])) + (point[1] - rotate_by[1]) * math.cos(math.radians(rotate_by[1])) + rotate_by[1]
        new_polygon.append((new_x, new_y))
    return new_polygon

def convex_hull(polygon):
    """Compute the convex hull of a polygon."""
    hull = []
    for i, point in enumerate(polygon):
        while len(hull) > 1 and not ccw(hull[-2], hull[-1], point):
            hull.pop()
        if point not in hull:
            hull.append(point)
    return hull

def ccw(p1, p2, p3):
    """Check if the triangle p1-p2-p3 points away from the origin."""
    return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p3[0] - p1[0]) * (p2[1] - p1[1]) > 0

def reorient_polygon(polygon, rotate_by):
    """Reorient a polygon by adding and splitting."""
    top = []
    bottom = []
    for point in polygon:
        if point[1] > rotate_by:
            top.append(point)
        else:
            bottom.append(point)
    new_polygon = convex_hull(top) + (rotate(polygon, rotate_by) + bottom)
    return new_polygon

