from heapq import heappush, heappop
from math import inf

def bellman_ford(graph, start):
    distance = [inf] * len(graph)
    distance[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        if current_distance > distance[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance_length = weight + current_distance
            if distance_length < distance[neighbor]:
                distance[neighbor] = distance_length
                heappush(priority_queue, (distance_length, neighbor))

    return distance

def find_heaviest_distance(city1, city2, graph, n):
    distances = []
    for v in range(1, n + 1):
        distance = bellman_ford(graph, v) 
        distances.append((-distance[city1], city1, v))
        distances.append((-distance[city2], city2, v))
    distances = sorted(distances)
    return sum(-(d[0] if d[1] == city1 else -d[0]) for d in distances[1:])

def game(tavas, nafas, graph, n, start, end):
    pavansh_points = find_heaviest_distance(tavas, nafas, graph, n)
    if pavansh_points > 0 and nth_element(points, 0, n - 1) == n - 1:
        return 'Break a heart'
    elif pavansh_points < 0:
        return 'Cry'
    else:
        return 'Flowers'

def nth_element(points, left, right):
    if left == right:
        return left

    pivot_index = left + (right - left) // 2
    pivot = points[pivot_index]

    left_index = right_index = pivot_index

    while left_index <= right:
        while points[left_index] < pivot:
            left_index += 1
        while points[right_index] > pivot:
            right_index -= 1

        if left_index < right_index:
            points[left_index], points[right_index] = points[right_index], points[left_index]

        left_index += 1
        right_index -= 1

    if right_index == n - 1:
        return right_index  
    if left_index == n - 1:
        return left_index

    # Move elements around the pivot element, right to left
    for i in range(right_index + 1):
        while left_index >= i and points[left_index] < pivot:
            left_index -= 1

        while right_index >= i and points[right_index] > pivot:
            right_index -= 1

        points[i], points[right_index] = points[right_index + i], points[left_index + i + 1]

    return right_index

