    original_starts = [str(16 ** i) for i in range(n - 1, -1, -1)]
    matched_digits = 0
    if original_diff[0] == '0':
        matched_digits = 1
    elif original_diff[0] != '0':
        for digit in original_diff:
            if digit == '0':
                matched_digits += 1

    # If the first character is 0, it can be in any position due to the zero-extension, but it's neither 0 or 9, so it must be in the first position.
    if original_diff != '000':
        matched_digits += 1

    invert_diff = int(original_diff, 16) * 16 ** n - 1
    max_of_length = original_diff
    max_digit = 0
    while True:
        digits = list(str(invert_diff // 16 ** 3))
        decoded_len = n - matched_digits
        index = 0
        while decoded_len > 0:
            zero_placed = False
            while digits[index] != original_starts[decoded_len - 1].lower():
                if digits[index] == original_starts[decoded_len - 1].upper():
                    digits[index] = original_starts[decoded_len - 1].lower()
                    zero_placed = True
                index += 1
            if not zero_placed:
                while index < len(digits) and digits[index] == '0':
                    index += 1
            decoded_len -= 1
        invert_diff = 16 * int(''.join(digits), 16) + 1

