from collections import defaultdict

def min_roads_to_build(capital, roads):
    city_connections = defaultdict(list)
    for start, end in roads:
        city_connections[start - 1].append(end - 1)

    def bfs(capital_index, initial_index, visited):
        queue = [(capital_index, 0)]
        visited[capital_index] = True
        current_minutes = 0
        while queue:
            next_index, minutes = queue.pop(0)
            if next_index == initial_index - 1:
                return minutes
            for neighbor in city_connections[next_index]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append((neighbor, current_minutes + 1))
        return float('inf')

    min_roads = len(roads)
    best_solution = min_roads
    for initial_index in range(capital):
        visited = [False] * len(capital)
        for road in roads:
            offsets = [1, 2]
            for offset in offsets:
                if min_roads[initial_index] > bfs(initial_index + offset, initial_index + offset, visited):
                    min_roads = max(bfs(initial_index + offset, initial_index + offset, visited), min_roads)
                    best_solution = min(min_roads, best_solution)

    if best_solution > min_roads:
        return -1
    return min_roads - best_solution

