from collections import defaultdict

def max_fraction(n, weights, edges):
    dp = [[-float('inf')] * (n + 1) for _ in range(n + 1)]
    parent = {i: i for i in range(n)}
    depth = defaultdict(lambda: 0)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        parent[rootY] = rootX
        return rootX

    def dfs(root, parent, depth):
        for u, v in edges:
            if u == parent or v == parent:
                continue
            union(u, v)
            dfs(u, v, depth)
            for i in range(n + 1):
                dp[root][i] = max(dp[root][i], dp[parent][i] + depth[root from u])

    for root in range(n):
        dfs(root, root, depth[root])

    result = max(dp[root], key=dp[root].__getitem__)
    if result > 0:
        return str(max_fraction(weights - dp[root], weights - result, dp, parents), result) + " " + str(depth[root])
    return str(result) + " " + str(max(depth[i] for i, d in depth.items() if d > 0))

import math

def max_fraction(weights, children):
