    graph = defaultdict(list)
    for _ in range(M):
        a, b = map(int, input().split())
        graph[a].append(b)

    visited = [False] * (N + 1)
    def dfs(start):
        for neighbor in graph[start]:
            if visited[neighbor]:
                continue
            visited[neighbor] = True
            sub_graph = dfs(neighbor)
            if len(sub_graph) < len(visited[start:]):
                visited[start:][sub_graph] = start
            else:
                return sub_graph
        visited[start] = start
        return [start]

    for i in range(1, N + 1):
        if not visited[i]:
            dfs(i)

    # Determine the capital city
    capital = max([visited[start:] for start in range(1, N + 1)])
    if not capital:
        return -1

    # Check if there's a way to break Chef's disappointment
    end_positions = []
    for vertex in range(1, N + 1):
        sub_graph = [visited[start:] for start in range(1, N + 1) if visited[start] > vertex]
        if not sub_graph:
            continue
        end_positions.extend([sub[-1] for sub in sub_graph])

    # Check if there's a path from capital not including the existing roads
    for edge in graph:
        if set(end_positions).issuperset([visited[edge]] * len(end_positions)):
            graph.pop(edge)

