import heapq
from collections import defaultdict

def dijkstra(graph, start):
    n = len(graph)
    distances = defaultdict(lambda: float('inf'))
    distances[start] = 0

    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_city = heapq.heappop(priority_queue)

        if current_distance > distances[current_city]:
            continue

        for neighbor, weight in graph[current_city]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def lifes_after_game(s, t, p, graph):
    n = len(p)
    graph = defaultdict(list)

    for u, v, w in graph:
        graph[u - 1].append((v - 1, w))
        graph[v - 1].append((u - 1, w))

    dist = dijkstra(graph, s - 1)
    Tavas_score = sum([p[n - 1] for n in range(1, n + 1)])
    Nafas_score = 0

    winners = 0
    loser = None
    tie = False

    for i in range(n):
        for j in range(n):
            if i == j or dist[i][j] < float('inf'):
                continue

            winner = 0
            for z in range(n):
                if (i, z) in graph and j != z and dist[i][z] == float('inf'):
                    winner += p[z]

            if winner > 0 and i != s - 1:
                Tavas_score -= p[i]
                Nafas_score += winner
                winners += 1
                loser = s - 1

    if Tavas_score > Nafas_score:
        print("Break a heart")
    elif Nafas_score < Tavas_score:
        print("Cry")
    else:
        print("Flowers")

    if ties > 0 and (winners == 1 and not tie):
        print("Use Standard Input format")
