from collections import deque

def shortest_crisp_string(n, p, initial_string, adjacency_matrix):
    # Dictionary to map letters to their positions
    letter_position = {chr(ord('a') + i): i for i in range(p)}
    # Map of positions of letters 
    position_letter = {v: k for k, v in letter_position.items()}
    deque_positions = deque(position for position in range(n) if initial_string[position] in letter_position)
    edge_edges = []

    for i, j in enumerate(adjacency_matrix):
        for position in range(p):
            if i == position:
                edge_edges.append([i, i])
            elif j[position]:
                edge_edges.append([position_letter[position], position])

    pq = [deque_positions]
    while pq:
        positions = pq.pop()
        if len(set(positions)) == 2:  # Edge case where all positions are the same
            return 2 * len(initial_string)
        available = []
        for initial, successor in edge_edges:
            if initial in positions:
                available.append(successor)
        if not available:
            continue
        pq.extend(deque(positions[:]))
        for successor in available:
            tmp = tuple(pos for pos in positions)
            tmp.remove(tmp[positions.index(successor)])
            pq.append(tmp)

    return len(initial_string)

