from collections import defaultdict
import sys

def reconstruct_graph(n, m, edges):
    if n > m:
        return -1

    graph = defaultdict(lambda: [])
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    adjacency_list = list(graph.items())

    def dfs(u, visited):
        visited.add(u)
        for v in adjacency_list[u]:
            if v in visited:
                return True
            if dfs(v, visited):
                return True
        return False

    possible_edges = set([tuple(sorted(pair)) for pair in adjacency_list])

    result = []

    for node in adjacency_list:
        for neighbor in node[1]:
            if neighbor not in possible_edges:
                edge = (node[0], neighbor)
                node_edges = [edge]
                for nei in node[1]:
                    if nei not in {node[0], neighbor}:
                        new_edge = (nei, neighbor)
                        node_edges.append(new_edge)
                        break
                result.extend(node_edges[::-1])
                break           

    return "\n".join([" ".join(map(str, pairs)) for pairs in result])

def main():
    _, m = map(int, input().split())
    edges = [list(map(int, input().split())) for _ in range(m)]
    print(reconstruct_graph(_, m, edges))

if __name__ == "__main__":
    main()
