from typing import List
import math

def max_selling_goods(n: int, c: int, prods: List[int], sales: List[int]) -> int:
    if n > c:
        return sum(prods)
    else:
        c -= n - 1
        # first traverse prod from shortest to longest
        min_idx = 0
        for i in range(1, n):
            if prods[i] < prods[min_idx]:
                min_idx = i 
        # looking only on min_idx,
        # randomly distribute on graph
        while c > 0:
            run = min(c, math.ceil((prods[min_idx] - sales[min_idx] + 1) / prods[min_idx]))
            sales[min_idx] -= run
            prods[min_idx] -= run
            c -= run
            if min_idx == n - 1:
                min_idx = 0
            else:
                min_idx += 1
        return sum(prods)

n, c = map(int, input().split())
prods = list(map(int, input().split()))
sales = list(map(int, input().split()))
print(max_selling_goods(n, c, prods, sales))
